      "body": "有人把电影《猜火车》最后那几秒，做成一个很小的网页装置。打开先看见三个词：Choose Life。开声音，点一下，等一两分钟。作者说一直爱那段结尾，也爱那首歌 Born Slippy，想让网页也喘那口气。Hacker News 上只有几票，帖子几乎没讨论。但原文在，耳机一戴就能进。所以呢：不是影评，不是二创混剪。是把一段片尾做成你可以走进去的房间。戴上耳机，别提前关。",
