      "body": "浏览器自带的弹窗只会问你一句话，再还你一个字符串。有人把同一姿势扩成「问你一整张表」。代码里写一行等待询问，对话框自己画出来，填完返回一个对象。演示里三层对话框叠着：发布说明底下再打开定时，定时里再加一段不许发布的窗口。没有组件要挂到页面上，没有表单状态要自己管。作者说，其他表单库给你一个要安放的零件，这个给你一个可以调用的问题。所以呢：问用户要数据，本该像那句老弹窗一样，问完就走。",
