      "title": "下载模型之前，先问这台电脑",
      "body": "广告从不说你的电脑跑不跑得动。有人做了 llmfit，扫你的内存和显卡，给每个模型打分：塞不塞得下、快不快、聪明不聪明。一条命令打开表格。测完真实速度还能交回去，下一版别人同款电脑就能看见实测，不必自己再跑一遍。今天它又冲上 GitHub 热榜。所以呢：下载之前先问这台机器，别问海报。",
